import React, { useState, useEffect, useRef, useCallback } from 'react';
import io from 'socket.io-client';
import { Avatar3D } from '../components/Avatar3D';
import { ShareModal } from '../components/ShareModal';
import { VideoPlayerModal } from '../components/VideoPlayerModal';
import { SidePanel } from '../components/SidePanel';
import { CallControls } from '../components/CallControls';
import { useVoiceInput } from '../hooks/useVoiceInput';
import { sendChatMessage } from '../utils/api';
import { speakText, stopSpeaking } from '../utils/speechSynthesis';
import toast, { Toaster } from 'react-hot-toast';

const socket = io('http://localhost:8000', {
  transports: ['websocket'],
  reconnection: true,
});

export const VideoCallPage = ({ companion, roomId, userId, onEndCall }) => {
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(false);
  const [mediaStream, setMediaStream] = useState(null);
  const [isCameraLoading, setIsCameraLoading] = useState(true);
  const [isScreenSharing, setIsScreenSharing] = useState(false);
  const [screenStream, setScreenStream] = useState(null);
  const [callTime, setCallTime] = useState(0);
  const [isRecording, setIsRecording] = useState(false);
  const [isShareModalOpen, setShareModalOpen] = useState(false);
  const [activePanel, setActivePanel] = useState('chat');
  const [isMenuOpen, setMenuOpen] = useState(false);
  const [reactions, setReactions] = useState([]);
  const [playingVideoId, setPlayingVideoId] = useState(null);
  const [messages, setMessages] = useState([]);
  const [currentAudio, setCurrentAudio] = useState(null);
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [hasPlayedIntro, setHasPlayedIntro] = useState(false);
  const [customAnimation, setCustomAnimation] = useState(null);
  const [participants, setParticipants] = useState([]);
  const [remoteStreams, setRemoteStreams] = useState({});

  const peerConnections = useRef({});
  const hasJoinedRoom = useRef(false);
  const userVideoRef = useRef(null);
  const screenVideoRef = useRef(null);
  const mediaStreamRef = useRef(null);
  const screenStreamRef = useRef(null);
  const timerRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunksRef = useRef([]);

  // ✅ Initialize camera
  useEffect(() => {
    const initCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { width: 1280, height: 720 },
          audio: true
        });

        setMediaStream(stream);
        mediaStreamRef.current = stream;

        if (userVideoRef.current) {
          userVideoRef.current.srcObject = stream;
        }

        setIsCameraLoading(false);
      } catch (err) {
        console.error('Camera error:', err);
        toast.error('Camera access denied');
        setIsCameraLoading(false);
      }
    };

    initCamera();
    timerRef.current = setInterval(() => setCallTime(t => t + 1), 1000);

    return () => {
      clearInterval(timerRef.current);
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  // ✅ Handle mic toggle
  const handleMicToggle = () => {
    if (mediaStream) {
      mediaStream.getAudioTracks().forEach(track => {
        track.enabled = !track.enabled;
      });
      setIsMuted(!isMuted);
    }
  };

  // ✅ Handle camera toggle
  const handleCameraToggle = () => {
    if (mediaStream) {
      mediaStream.getVideoTracks().forEach(track => {
        track.enabled = !track.enabled;
      });
      setIsVideoOff(!isVideoOff);
    }
  };

  // ✅ Recording with DisplayMedia (captures entire screen)
  const handleRecordingToggle = async () => {
    if (!isRecording) {
      try {
        // Ask user to select what to record
        const displayStream = await navigator.mediaDevices.getDisplayMedia({
          video: { mediaSource: 'screen' },
          audio: true
        });

        // Add mic audio
        if (mediaStream) {
          const audioTrack = mediaStream.getAudioTracks()[0];
          if (audioTrack) {
            displayStream.addTrack(audioTrack.clone());
          }
        }

        const options = { 
          mimeType: 'video/webm;codecs=vp8,opus',
          videoBitsPerSecond: 2500000
        };

        mediaRecorderRef.current = new MediaRecorder(displayStream, options);
        recordedChunksRef.current = [];

        mediaRecorderRef.current.ondataavailable = (e) => {
          if (e.data && e.data.size > 0) {
            recordedChunksRef.current.push(e.data);
          }
        };

        mediaRecorderRef.current.onstop = () => {
          const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `call-recording-${Date.now()}.webm`;
          a.click();
          URL.revokeObjectURL(url);
          
          displayStream.getTracks().forEach(t => t.stop());
          toast.success('📹 Recording saved!');
        };

        mediaRecorderRef.current.start(100); // Save data every 100ms
        setIsRecording(true);
        toast.success('🔴 Recording started - Select window to record');

        // Auto-stop when user stops sharing
        displayStream.getVideoTracks()[0].onended = () => {
          if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
            mediaRecorderRef.current.stop();
            setIsRecording(false);
          }
        };

      } catch (err) {
        console.error('Recording error:', err);
        toast.error('Recording failed');
      }
    } else {
      if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
        mediaRecorderRef.current.stop();
        setIsRecording(false);
        toast.success('⏹️ Recording stopped');
      }
    }
  };

  const toggleScreenShare = async () => {
    if (isScreenSharing) {
      if (screenStreamRef.current) {
        screenStreamRef.current.getTracks().forEach(t => t.stop());
      }
      setScreenStream(null);
      setIsScreenSharing(false);
    } else {
      try {
        const stream = await navigator.mediaDevices.getDisplayMedia({ video: true });
        setScreenStream(stream);
        screenStreamRef.current = stream;
        setIsScreenSharing(true);

        stream.getVideoTracks()[0].onended = () => {
          setScreenStream(null);
          setIsScreenSharing(false);
        };
      } catch (err) {
        console.error('Screen share error:', err);
      }
    }
  };

  const sendReaction = (emoji) => {
    const newReaction = { id: Date.now(), emoji, left: Math.random() * 80 + 10 };
    setReactions(prev => [...prev, newReaction]);
    setTimeout(() => setReactions(prev => prev.filter(r => r.id !== newReaction.id)), 4000);
  };

  const handlePlayAnimation = useCallback((animationId) => {
    setCustomAnimation(animationId);
    setTimeout(() => setCustomAnimation(null), 8000);
  }, []);

  const handleStopAI = useCallback(() => {
    stopSpeaking();
    if (currentAudio) {
      currentAudio.pause();
      currentAudio.currentTime = 0;
      setCurrentAudio(null);
    }
    setIsAISpeaking(false);
  }, [currentAudio]);

  const playAudio = useCallback(async (audioUrl, fallbackText) => {
    try {
      if (currentAudio) {
        currentAudio.pause();
        setCurrentAudio(null);
      }

      setIsAISpeaking(true);

      if (!audioUrl) {
        await speakText(fallbackText, companion?.id || 'omkar_ai');
        setIsAISpeaking(false);
        return;
      }

      const audio = new Audio(audioUrl);
      setCurrentAudio(audio);

      audio.play().catch(async () => {
        await speakText(fallbackText, companion?.id || 'omkar_ai');
        setIsAISpeaking(false);
      });

      audio.onended = () => {
        setCurrentAudio(null);
        setIsAISpeaking(false);
      };
    } catch (error) {
      console.error('Audio error:', error);
      setIsAISpeaking(false);
    }
  }, [currentAudio, companion]);

  const handleIntroComplete = useCallback(async (introData) => {
    if (!hasPlayedIntro && introData) {
      setHasPlayedIntro(true);
      setTimeout(async () => {
        const introMsg = {
          sender: 'ai',
          text: introData.message,
          timestamp: new Date().toISOString(),
        };
        setMessages([introMsg]);
        await playAudio(null, introData.message);
      }, 1500);
    }
  }, [hasPlayedIntro, playAudio]);

  const handleSendMessage = async (text) => {
    if (!text?.trim()) return;

    const userMessage = {
      sender: 'user',
      text,
      timestamp: new Date().toISOString(),
      userId: userId,
    };
    
    setMessages(prev => [...prev, userMessage]);

    try {
      const chatHistory = messages.slice(-10).map(m => ({
        role: m.sender === 'user' ? 'user' : 'assistant',
        content: m.text
      }));

      const response = await sendChatMessage(
        text,
        companion.id,
        roomId,
        companion.subject || 'General',
        0,
        chatHistory
      );

      const aiMessage = {
        sender: 'ai',
        text: response.text || response.message || 'I received your message.',
        timestamp: new Date().toISOString(),
        audioUrl: response.audioUrl || null,
        userId: companion.id,
      };
      
      setMessages(prev => [...prev, aiMessage]);
      await playAudio(response.audioUrl, aiMessage.text);
    } catch (error) {
      console.error('Error:', error);
    }
  };

  const handleVoiceResult = useCallback(async (transcript) => {
    if (!transcript?.trim()) return;

    const userMessage = {
      sender: 'user',
      text: transcript,
      timestamp: new Date().toISOString(),
      userId: userId,
    };
    
    setMessages(prev => [...prev, userMessage]);

    try {
      const chatHistory = messages.slice(-10).map(m => ({
        role: m.sender === 'user' ? 'user' : 'assistant',
        content: m.text
      }));

      const response = await sendChatMessage(
        transcript,
        companion.id,
        roomId,
        companion.subject || 'General',
        0,
        chatHistory
      );

      const aiMessage = {
        sender: 'ai',
        text: response.text || response.message || 'I received your message.',
        timestamp: new Date().toISOString(),
        audioUrl: response.audioUrl || null,
        userId: companion.id,
      };

      setMessages(prev => [...prev, aiMessage]);
      await playAudio(response.audioUrl, aiMessage.text);
    } catch (error) {
      console.error('Voice error:', error);
    }
  }, [companion, roomId, playAudio, userId, messages]);

  const { isListening, startListening, stopListening } = useVoiceInput({
    onResult: handleVoiceResult,
    language: 'en-US',
  });

  const formatTime = (seconds) =>
    `${Math.floor(seconds / 60).toString().padStart(2, '0')}:${(seconds % 60).toString().padStart(2, '0')}`;

  return (
    <>
      <Toaster position="top-center" />
      
      <div className="relative w-full h-screen bg-gradient-to-br from-gray-900 via-purple-900 to-indigo-900 overflow-hidden flex">
        {/* Avatar Section */}
        <div className="flex-1 relative flex items-center justify-center">
          <Avatar3D
            avatarMode={customAnimation || (isAISpeaking ? 'talk' : 'idle')}
            companionId={companion?.id || 'omkar_ai'}
            onIntroComplete={handleIntroComplete}
          />

          {/* Timer */}
          <div className="absolute top-4 left-4 bg-black/50 backdrop-blur-sm px-4 py-2 rounded-lg text-white flex items-center gap-2 z-10">
            <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
            <span className="font-mono">{formatTime(callTime)}</span>
          </div>

          {/* 3-Dot Menu */}
          <div className="absolute top-4 right-4 z-10">
            <button
              onClick={() => setMenuOpen(!isMenuOpen)}
              className="p-3 bg-gray-800/80 backdrop-blur-sm rounded-full hover:bg-gray-700 transition-colors"
            >
              <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 20 20">
                <circle cx="10" cy="5" r="1.5"/>
                <circle cx="10" cy="10" r="1.5"/>
                <circle cx="10" cy="15" r="1.5"/>
              </svg>
            </button>

            {isMenuOpen && (
              <div className="absolute right-0 top-full mt-2 w-56 bg-gray-800 rounded-lg shadow-2xl border border-gray-700 py-2">
                <button onClick={() => { setActivePanel('chat'); setMenuOpen(false); }}
                  className={`w-full px-4 py-2 text-left ${activePanel === 'chat' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>
                  💬 Chat
                </button>
                <button onClick={() => { setActivePanel('participants'); setMenuOpen(false); }}
                  className={`w-full px-4 py-2 text-left ${activePanel === 'participants' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>
                  👥 Participants
                </button>
                <button onClick={() => { setActivePanel('notes'); setMenuOpen(false); }}
                  className={`w-full px-4 py-2 text-left ${activePanel === 'notes' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>
                  📝 Notes
                </button>
                <button onClick={() => { setActivePanel('whiteboard'); setMenuOpen(false); }}
                  className={`w-full px-4 py-2 text-left ${activePanel === 'whiteboard' ? 'bg-blue-600 text-white' : 'text-gray-300 hover:bg-gray-700'}`}>
                  🎨 Whiteboard
                </button>
                <div className="my-2 border-t border-gray-700"></div>
                <div className="px-2 py-1 text-xs text-gray-500 uppercase">Avatar Actions</div>
                <button onClick={() => { handlePlayAnimation('walk'); setMenuOpen(false); }}
                  className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700 text-sm">🏃 Walk</button>
                <button onClick={() => { handlePlayAnimation('dance'); setMenuOpen(false); }}
                  className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700 text-sm">💃 Dance</button>
                <button onClick={() => { handlePlayAnimation('jump'); setMenuOpen(false); }}
                  className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700 text-sm">🦘 Jump</button>
                <div className="my-2 border-t border-gray-700"></div>
                <button onClick={() => { setShareModalOpen(true); setMenuOpen(false); }}
                  className="w-full px-4 py-2 text-left text-gray-300 hover:bg-gray-700">🔗 Share Room</button>
              </div>
            )}
          </div>

          {/* ✅ USER VIDEO - BOTTOM RIGHT */}
          <div className="absolute bottom-32 right-6 w-80 h-60 bg-black rounded-xl overflow-hidden border-4 border-blue-500 shadow-2xl z-20">
            {isCameraLoading ? (
              <div className="w-full h-full flex items-center justify-center">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-white"></div>
              </div>
            ) : (
              <>
                <video
                  ref={userVideoRef}
                  autoPlay
                  playsInline
                  muted
                  className="w-full h-full object-cover"
                  style={{ display: isVideoOff ? 'none' : 'block' }}
                />
                {isVideoOff && (
                  <div className="w-full h-full flex items-center justify-center bg-gray-900">
                    <div className="text-center">
                      <div className="w-20 h-20 bg-gray-700 rounded-full mx-auto mb-3 flex items-center justify-center">
                        <span className="text-4xl">👤</span>
                      </div>
                      <p className="text-white">Camera Off</p>
                    </div>
                  </div>
                )}
                <div className="absolute top-3 left-3 bg-black/70 px-3 py-1 rounded-lg text-sm text-white font-medium">
                  You {isMuted && '🔇'}
                </div>
              </>
            )}
          </div>

          {/* Screen Share */}
          {isScreenSharing && screenStream && (
            <div className="absolute top-20 left-6 w-80 h-60 bg-black rounded-xl overflow-hidden border-4 border-green-500 shadow-2xl z-10">
              <video ref={screenVideoRef} autoPlay playsInline className="w-full h-full object-contain" />
              <div className="absolute top-3 left-3 bg-green-600 px-3 py-1 rounded-lg text-sm text-white font-medium">
                Screen Share
              </div>
            </div>
          )}

          {/* Reactions */}
          {reactions.map(r => (
            <div key={r.id} className="absolute bottom-32 text-4xl animate-bounce-up pointer-events-none z-10"
              style={{ left: `${r.left}%` }}>{r.emoji}</div>
          ))}

          {/* Call Controls */}
          <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 z-20">
            <CallControls
              isMuted={isMuted}
              setIsMuted={handleMicToggle}
              isVideoOff={isVideoOff}
              setIsVideoOff={handleCameraToggle}
              isScreenSharing={isScreenSharing}
              toggleScreenShare={toggleScreenShare}
              sendReaction={sendReaction}
              isRecording={isRecording}
              setIsRecording={handleRecordingToggle}
              onEndCall={onEndCall}
            />
          </div>
        </div>

        {/* Side Panel */}
        <div className="w-[30%] border-l border-gray-700 bg-gray-900">
          <SidePanel
            activePanel={activePanel}
            setActivePanel={setActivePanel}
            messages={messages}
            onSendMessage={handleSendMessage}
            roomId={roomId}
            companion={companion}
            userId={userId}
            onStopAI={handleStopAI}
            startListening={startListening}
            stopListening={stopListening}
            isListening={isListening}
            participants={[
              { userId: companion?.name || 'AI Tutor', role: 'AI', isOnline: true },
              { userId: userId.substring(0, 12) + '...', role: 'You', isOnline: true },
            ]}
          />
        </div>
      </div>

      {isShareModalOpen && <ShareModal roomId={roomId} onClose={() => setShareModalOpen(false)} />}
      {playingVideoId && <VideoPlayerModal videoId={playingVideoId} onClose={() => setPlayingVideoId(null)} />}
    </>
  );
};
